package org.apache.commons.cli;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Assertions;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;

class Option_AddValueTest {

    @Test
    void testAddValueThrowsUnsupportedOperation_whenCalledDirectly() {
        Option opt = new Option("a", "some description");
        UnsupportedOperationException ex = Assertions.assertThrows(UnsupportedOperationException.class,
            () -> opt.addValue("value"));
        Assertions.assertEquals(
            "The addValue method is not intended for client use. Subclasses should use the processValue method instead.",
            ex.getMessage());
    }

    @Test
    void testAddValueViaReflection_invocationWrapsUnsupportedOperation() throws Exception {
        Option opt = new Option("b", true, "desc");
        Method m = Option.class.getDeclaredMethod("addValue", String.class);
        m.setAccessible(true);

        InvocationTargetException ite = Assertions.assertThrows(InvocationTargetException.class,
            () -> m.invoke(opt, "value"));

        Throwable cause = ite.getCause();
        Assertions.assertNotNull(cause);
        Assertions.assertTrue(cause instanceof UnsupportedOperationException);
        Assertions.assertEquals(
            "The addValue method is not intended for client use. Subclasses should use the processValue method instead.",
            cause.getMessage());
    }
}

